const MK_STEP=.1,MK_MAX_ROWS=6;function mkSquadMovers(players){const empty={risers:[],fallers:[],due:0,closing:0,netDue:0,total:0};if(typeof pwMovers!="function")return empty;const m=pwMovers(players||[],0),risers=m.risers||[],fallers=m.fallers||[],dueRisers=risers.filter(c=>c.tier==="due").length,dueFallers=fallers.filter(c=>c.tier==="due").length;return{risers,fallers,due:dueRisers+dueFallers,closing:risers.length+fallers.length-dueRisers-dueFallers,netDue:Math.round((dueRisers-dueFallers)*.1*10)/10,total:risers.length+fallers.length}}function mkRow(c){const rising=c.dir==="rise",from=c.player.price,to=rising?from+.1:from-.1,pct=Math.min(100,Math.round(Math.abs(c.progress))),label=typeof pwLabel=="function"?pwLabel(c):pct+"%",detail=typeof pwDetail=="function"?pwDetail(c):"",mark=typeof v2IdentityHTML=="function"?`<span class="mk-face">${v2IdentityHTML(c.player,"v2-pid-portrait")}</span>`:"";return`<div class="mk-row ${rising?"up":"down"}${c.tier==="due"?" is-due":""}"
                data-tooltip="${escHTML(`${c.player.name} \u2014 ${detail}`)}">
                <span class="mk-arrow" aria-hidden="true">${rising?"\u25B2":"\u25BC"}</span>
                ${mark}
                <span class="mk-name">${escHTML(c.player.name)}</span>
                <span class="mk-price">\xA3${from.toFixed(1)}<i>\u2192</i>\xA3${to.toFixed(1)}</span>
                <span class="mk-meter" aria-hidden="true"><i style="width:${pct}%"></i></span>
                <span class="mk-tag">${escHTML(label)}</span>
            </div>`}function mkColumn(list,rising){const title=rising?"Rising":"Falling",why=rising?"Players you own getting more expensive. Good news: your squad value goes up, and selling later costs you nothing.":"Players you own getting cheaper. Your squad value falls, and you lose money you cannot get back.";if(!list.length)return`<div class="mk-col ${rising?"up":"down"}">
                    <div class="mk-col-head"><span class="mk-col-t">${rising?"\u25B2":"\u25BC"} ${title}</span>
                        <span class="mk-col-n">0</span></div>
                    <div class="mk-none">Nobody in your squad is close to a ${rising?"rise":"drop"}.</div>
                </div>`;const shown=list.slice(0,6),hidden=list.length-shown.length;return`<div class="mk-col ${rising?"up":"down"}">
                <div class="mk-col-head" data-tooltip="${escHTML(why)}">
                    <span class="mk-col-t">${rising?"\u25B2":"\u25BC"} ${title}</span>
                    <span class="mk-col-n">${list.length}</span></div>
                ${shown.map(mkRow).join("")}
                ${hidden>0?`<div class="mk-more">+${hidden} more</div>`:""}
            </div>`}function mkRenderPanel(movers){const m=movers;if(!m||!m.total)return`<div class="mk-panel">
                    <div class="mk-head"><span class="mk-title">${v2Icon("trend")}Your market</span>
                        <span class="mk-sub">Nothing in your squad is near a price change.</span></div>
                </div>`;const net=m.netDue,netCls=net>0?"up":net<0?"down":"flat",netTxt=net>0?`+\xA3${net.toFixed(1)}m`:net<0?`\u2212\xA3${Math.abs(net).toFixed(1)}m`:"\xA30.0m";return`<div class="mk-panel">
                <div class="mk-head">
                    <span class="mk-title">${v2Icon("trend")}Your market</span>
                    ${m.due?`<span class="mk-net ${netCls}" data-tooltip="${escHTML(`${m.due} of your players ${m.due===1?"has":"have"} a full meter, so ${m.due===1?"it changes":"they change"} at the next daily update. That is a net ${netTxt} to your squad value. Players merely closing in are not counted here \u2014 most of them do not move tonight.`)}">
                            ${netTxt}<em>tonight</em></span>`:`<span class="mk-sub">${m.closing} closing in, none due tonight</span>`}
                    ${m.due&&m.closing?`<span class="mk-sub">${m.closing} more closing in</span>`:""}
                </div>
                <div class="mk-cols">
                    ${mkColumn(m.risers,!0)}
                    ${mkColumn(m.fallers,!1)}
                </div>
            </div>`}function mkRenderInto(players,id){const el=document.getElementById(id||"v2Market");if(!el)return null;const movers=mkSquadMovers(players);return el.innerHTML=mkRenderPanel(movers),el.style.display="",typeof lucide<"u"&&lucide.createIcons(),movers}
